g.lines.forEach(l => {
  l.key   = pcKeyBdc(g.thuISO, l.aptKey);
  if (!marks[l.key]) {
    var liveKeys = g.lines.map(function (x) { return pcKeyBdc(g.thuISO, x.aptKey); });
    var staleFit = Object.keys(marks).filter(function (k) {
      if (k.indexOf('bdc|' + g.thuISO + '|') !== 0) return false;
      if (liveKeys.indexOf(k) >= 0) return false;
      var m = marks[k];
      var mv = (m && m.amt != null && m.amt !== '') ? +m.amt : (m ? +m.exp : NaN);
      return isFinite(mv) && Math.abs(mv - l.exp) <= 0.011;
    });
    var siblings = staleFit.length === 1 ? g.lines.filter(function (o) {
      if (pcKeyBdc(g.thuISO, o.aptKey) === l.key || marks[pcKeyBdc(g.thuISO, o.aptKey)]) return false;
      var m = marks[staleFit[0]];
      var mv = (m && m.amt != null && m.amt !== '') ? +m.amt : (m ? +m.exp : NaN);
      return isFinite(mv) && Math.abs(mv - o.exp) <= 0.011;
    }) : [];
    if (staleFit.length === 1 && !siblings.length) {
      marks[l.key] = marks[staleFit[0]];
      if (typeof window !== 'undefined') window._pcStaleMigrated = true;
    }
  }
  l.mark  = marks[l.key] || null;

